-- Events are generated by committed domain transitions, never by a client-supplied notification RPC.
alter table public.notifications drop constraint if exists notifications_type_check;
alter table public.notifications add constraint notifications_type_check check(type in ('meeting_invitation','meeting_updated','meeting_cancelled','meeting_action_assigned','chat_mention','chat_direct_message','chat_channel_message','team_registration_pending','material_approved','material_changes_requested','member_birthday','calendar_approved','calendar_changes_requested','calendar_production','client_created','task_production_started'));
create function private.operational_notification_access(a uuid,u uuid,p text) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.agency_members m join public.roles r on r.id=m.role_id and r.agency_id=m.agency_id join public.agencies ag on ag.id=m.agency_id where m.agency_id=a and m.user_id=u and m.status='active' and ag.status='active' and (r.name='OWNER' or exists(select 1 from public.role_permissions rp join public.permissions pm on pm.id=rp.permission_id where rp.role_id=r.id and rp.allowed and pm.permission_key=p)));
$$;
create function private.notify_calendar_transition() returns trigger language plpgsql security definer set search_path='' as $$
declare event_type text;event_title text;client_name text;
begin
 if new.status is not distinct from old.status or new.status not in ('approved','changes_requested','production') then return new;end if;
 if not exists(select 1 from public.clients where id=new.client_id and agency_id=new.agency_id) then return new;end if;
 -- Public client feedback has no auth.uid(); the existing token-validated RPC and campaign guard authorize the transition.
 event_type:=case new.status when 'approved' then 'calendar_approved' when 'changes_requested' then 'calendar_changes_requested' else 'calendar_production' end;
 event_title:=case new.status when 'approved' then 'Calendário aprovado pelo cliente' when 'changes_requested' then 'Cliente solicitou ajustes no calendário' else 'Calendário liberado para produção' end;
 select name into client_name from public.clients where id=new.client_id and agency_id=new.agency_id;
 insert into public.notifications(agency_id,recipient_id,type,title,body,resource_type,resource_id)
 select new.agency_id,m.user_id,event_type,event_title,client_name||' · '||to_char(new.month,'MM/YYYY')||'. Confira a campanha e os próximos passos.','editorial_campaign',new.id
 from public.agency_members m join public.roles r on r.id=m.role_id and r.agency_id=m.agency_id
 where m.agency_id=new.agency_id and m.user_id is distinct from auth.uid() and private.operational_notification_access(new.agency_id,m.user_id,'strategy.view')
 and (r.name in ('OWNER','ADMIN','MANAGER','GESTOR') or exists(select 1 from public.briefings b where b.id=new.briefing_id and b.agency_id=new.agency_id and b.client_id=new.client_id and b.assigned_to=m.user_id));
 return new;
end;$$;
create function private.notify_client_created() returns trigger language plpgsql security definer set search_path='' as $$
begin
 -- Bulk imports/service writes do not create a burst of operational notifications.
 if auth.uid() is null or not private.can_editorial(new.agency_id,'clients.create') then return new;end if;
 insert into public.notifications(agency_id,recipient_id,type,title,body,resource_type,resource_id)
 select new.agency_id,m.user_id,'client_created','Novo cliente cadastrado',new.name||' foi adicionado à agência.','client',new.id
 from public.agency_members m join public.roles r on r.id=m.role_id and r.agency_id=m.agency_id
 where m.agency_id=new.agency_id and r.name in ('OWNER','ADMIN','MANAGER','GESTOR') and m.user_id<>auth.uid() and private.operational_notification_access(new.agency_id,m.user_id,'clients.view');
 return new;
end;$$;
create function private.notify_task_production_started() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.status is not distinct from old.status or new.status<>'in_progress' or auth.uid() is null or not exists(select 1 from public.agency_members m join public.agencies a on a.id=m.agency_id where m.agency_id=new.agency_id and m.user_id=auth.uid() and m.status='active' and a.status='active') then return new;end if;
 if not exists(select 1 from public.projects where id=new.project_id and agency_id=new.agency_id) then return new;end if;
 insert into public.notifications(agency_id,recipient_id,type,title,body,resource_type,resource_id)
 select new.agency_id,m.user_id,'task_production_started','Demanda entrou em produção',new.title||' está em produção.','task',new.id
 from public.agency_members m join public.roles r on r.id=m.role_id and r.agency_id=m.agency_id
 where m.agency_id=new.agency_id and m.user_id<>auth.uid() and private.operational_notification_access(new.agency_id,m.user_id,'tasks.view')
 and (exists(select 1 from public.task_assignees ta where ta.agency_id=new.agency_id and ta.task_id=new.id and ta.user_id=m.user_id) or r.name in ('OWNER','ADMIN','MANAGER','GESTOR'))
 and (r.name in ('OWNER','ADMIN') or exists(select 1 from public.project_members pm where pm.agency_id=new.agency_id and pm.project_id=new.project_id and pm.user_id=m.user_id) or exists(select 1 from public.projects p where p.id=new.project_id and p.agency_id=new.agency_id and (p.created_by=m.user_id or p.owner_id=m.user_id)));
 return new;
end;$$;
revoke all on function private.operational_notification_access(uuid,uuid,text),private.notify_calendar_transition(),private.notify_client_created(),private.notify_task_production_started() from public,anon,authenticated;
create trigger operational_calendar_notification after update of status on public.monthly_editorial_campaigns for each row execute function private.notify_calendar_transition();
create trigger operational_client_notification after insert on public.clients for each row execute function private.notify_client_created();
create trigger operational_task_notification after update of status on public.tasks for each row execute function private.notify_task_production_started();
